  -- Fetch record first
  SELECT * INTO v_result
  FROM sites
  WHERE id = p_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Record not found: % with id=%', 'sites', p_id;
  END IF;

  -- Check delete permission
  IF NOT can_delete_sites(p_user_id, to_jsonb(v_result)) THEN
